    const pos=throneRtsArmyPosition(a); out.push({kind:'canonical',id:a.id,x:pos.x,y:heightAt(pos.x,pos.z)+3,z:pos.z,label:`Field company · ${throneRtsNumber(a.n)} troops`,color:REALMS[a.r].color});
